from taf.collectors.core.templates.dynamic_class_creation import Using
from taf.collectors.core import StartableCollector, ManagedObject
from taf.collectors.core.entities.executor import ExecutionError
import logging
import os

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class TtiTraceServer4G(Using("tool_executor"),
                       ManagedObject):
    """
    TTI trace server (4G) used and shared by TTI trace streaming clients (see TtiTrace4GCollector). It performs setup
    and teardown of TTI trace server (using TTITraceServer.linux).
    """

    def __init__(self,
                 enb_ip='192.168.255.1',
                 ttitrace_server_path='/opt/TtiTraceServer/TTITraceServer.linux',
                 **kwargs):
        super(TtiTraceServer4G, self).__init__(**kwargs)
        self._enb_ip = enb_ip
        self.ttitrace_server_dir = os.path.dirname(ttitrace_server_path)
        self._ttitrace_server = os.path.basename(ttitrace_server_path)

    def _setup(self):
        self._sudo_prefix = self._tool_executor.sudo_prefix()
        self._process_and_file_cleanup()
        self._tool_executor.execute(
            "cd {ttitrace_server_dir} && ./{ttitrace_server} --config --enb {enb_ip} 15003".format(
                ttitrace_server_dir=self.ttitrace_server_dir,
                ttitrace_server=self._ttitrace_server,
                enb_ip=self._enb_ip).encode('utf-8'))
        self._server_process = self._tool_executor.start(
            "cd {ttitrace_server_dir} && ./{ttitrace_server}".format(
                ttitrace_server_dir=self.ttitrace_server_dir,
                ttitrace_server=self._ttitrace_server).encode('utf-8'),
            use_tty=True)
        self._wait_for_start_completed()

    def _wait_for_start_completed(self):
        stdout_output = self._server_process.stdout.read_line(timeout=1)
        for _ in range(1, 7):
            stdout_output += self._server_process.stdout.read_line(timeout=1)
            if b"The TTI Trace Server" in stdout_output:
                break
        if b'The TTI Trace Server shall send syscom packets whose payload is Big endian.' not in stdout_output:
            if not self._server_process.is_running:
                stdout_output += self._server_process.stdout.read(timeout=0.1)
                stderr_output = self._server_process.stderr.read(timeout=0.1)
                exit_status = self._server_process.exit_status
            else:
                stderr_output = b''
                exit_status = None
            raise ExecutionError(
                stdout=stdout_output,
                stderr=stderr_output,
                exit_status=exit_status)

    def _teardown(self):
        self._server_process.stdin.write("\x03".encode())
        try:
            self._wait_till_process_terminated()
        except TimeoutError as exception:
            logger.debug("Process did not terminate gracefully, forcing cleanup: %r", exception)
            self._process_and_file_cleanup()
        else:
            self._file_cleanup()

    def _wait_till_process_terminated(self):
        self._server_process.wait(timeout=2)

    def _process_and_file_cleanup(self):
        try:
            self._tool_executor.execute(
                '{sudo_prefix}pkill -9 -f {tti_server}'.format(
                    sudo_prefix=self._sudo_prefix,
                    tti_server=self._ttitrace_server).encode())
        except ExecutionError as exception:
            logger.debug("Terminating %r process failed: %r", self._ttitrace_server, exception)
        self._file_cleanup()

    def _file_cleanup(self):
        self._tool_executor.execute(
            '{sudo_prefix}rm -f {log_dir}/settings.xml'.format(
                sudo_prefix=self._sudo_prefix,
                log_dir=self.ttitrace_server_dir).encode())
        self._tool_executor.execute(
            '{sudo_prefix}rm -f {log_dir}/tti_stream*.dat'.format(
                sudo_prefix=self._sudo_prefix,
                log_dir=self.ttitrace_server_dir).encode())


class TtiTrace4GCollector(Using("tool_executor"),
                          Using("file_getter"),
                          Using("tool"),
                          StartableCollector):
    """
    TTI trace streaming client (4G) class to perform start, stop and collect Tti trace files (using
    TTITraceStreamingClient.linux). Setup and teardown of TtiTraceServer will be taken care by TtiTraceServer4G instance
    passed as tool.
    """

    def __init__(self,
                 global_cell_id,
                 ttitrace_client_path='/opt/TtiTraceServer/TTITraceStreamingClient/TTITraceStreamingClient.linux',
                 file_name='trace_file',
                 **kwargs):
        super(TtiTrace4GCollector, self).__init__(**kwargs)
        self._global_cell_id = global_cell_id
        self._ttitrace_client_dir = os.path.dirname(ttitrace_client_path)
        self._ttitrace_client = os.path.basename(ttitrace_client_path)
        self._file_name = file_name

    def _start(self):
        self._tool_executor.execute(
            'cd {ttitrace_client_dir} &&'
            ' ./{ttitrace_client} --params --command "start" --cellID {global_cell_id} --name {file_name}'.format(
                ttitrace_client_dir=self._ttitrace_client_dir,
                ttitrace_client=self._ttitrace_client,
                global_cell_id=self._global_cell_id,
                file_name=self._file_name).encode('utf-8'))

    def _stop(self):
        self._tool_executor.execute(
            'cd {ttitrace_client_dir} &&'
            ' ./{ttitrace_client} --params --command "stop" --cellID {global_cell_id} --name {file_name}'.format(
                ttitrace_client_dir=self._ttitrace_client_dir,
                ttitrace_client=self._ttitrace_client,
                global_cell_id=self._global_cell_id,
                file_name=self._file_name).encode('utf-8'))

    def _collect(self, target_dir):
        pattern = f"tti_stream_cell_{self._file_name}_{self._global_cell_id}*.dat"
        for file_path in self._glob(pattern):
            self._file_getter.get_file(
                source_path=file_path,
                target_path=os.path.join(target_dir, os.path.basename(file_path)))

    def _glob(self, pattern):
        """
        List files matching the TTI trace pattern using find command.
        Works for both local and remote executors, handles spaces in paths.

        :param str pattern: File name pattern to match
        """
        file_paths = self._tool_executor.execute(
            f'find "{self._tool.ttitrace_server_dir}" -maxdepth 1 -type f '
            f'-name "{pattern}"'
            .encode()).decode().splitlines()

        return file_paths
